COMMENT ON TABLE "portfolios"."chart_projection_state" IS 'Feature #253/#254: per-portfolio charting projection metadata. generation = currently published fact generation; version bumped on every invalidation; status is pending|complete|failed|stale; dirty_from is the earliest stale date.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_projection_state"."generation" IS 'Currently published fact generation; reads only see this generation.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_projection_state"."version" IS 'Bumped on every invalidation so a reader can detect a pending rebuild.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_projection_state"."dirty_from" IS 'Earliest date whose facts are stale; null when the projection is current.';--> statement-breakpoint
COMMENT ON TABLE "portfolios"."chart_position_daily" IS 'Feature #253/#254: one position-day fact (quantity, market value, remaining basis, realized gain, income, net flow). Attribution comes from the canonical transaction owner/replay, never by multiplying a global position quantity by every membership row.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_position_daily"."value" IS 'Market value on the day in the portfolio base currency; excludes unpriced positions.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_position_daily"."remaining_basis" IS 'Remaining cost basis on the day in the portfolio base currency.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_position_daily"."income" IS 'Received income (dividends/interest) attributed to the day, base currency.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_position_daily"."net_flow" IS 'Net external flow attributed to the day, base currency.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_position_daily"."price_known" IS 'False when the day had no price for the position; value then excludes it.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_position_daily"."carried_forward" IS 'True when the day price is a carried-forward close rather than a real bar.';--> statement-breakpoint
COMMENT ON TABLE "portfolios"."chart_event_facts" IS 'Feature #253/#254: normalized income/cash/funding event facts with source identity, so a dividend and its cash effect are never double counted. standalone marks cash events not generated by a trade; linked_position_id / source_transaction_id carry trade linkage so a linked cash effect follows the selected investment and is counted once.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_event_facts"."receipt_kind" IS 'dividend | interest | option | contribution | withdrawal | transfer | trade | cash.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_event_facts"."amount_base" IS 'Signed amount in the portfolio base currency.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_event_facts"."standalone" IS 'True for standalone cash events not generated by a trade.';--> statement-breakpoint
COMMENT ON COLUMN "portfolios"."chart_event_facts"."linked_position_id" IS 'Position whose investment history a linked cash effect follows.';